KG42.register("rules-75d844018eefeccfa2562d49",{"id":"35-microgrid_pool_strategy::v141-c-R008","paper":"35-microgrid_pool_strategy","record":{"rule_id":"v141-c-R008","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"The local distribution-system market-clearing model restricts PCC power exchanges to its feasible set, including exchange capacity bounds. Scope: MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM. Real and reactive MG power balances must ensure that DG generation supplies the entire load and the power exchange at the PCC. Scope: MG real and reactive power balances governing exchanges at the PCC. Both real and reactive MG exchange bounds are scaled by the binary variable controlling the working-mode switch. Scope: MG–DS real and reactive power exchanges in Case2. Condition: Case2 contingency study of switching between grid-connected and islanded operation.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","execution.energy_trade"],"E":[{"edge_id":"v141-c-R008-E001","source":"clearing.local","target":"execution.energy_trade","type":"limits","constraint_ids":["v141-c-R008-C001"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"MG real and reactive power balances governing exchanges at the PCC. | MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM. | MG–DS real and reactive power exchanges in Case2.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12","v141-b-g01-E18","v141-b-g02-E43"]},"x":[{"variable_id":"x_pcc_active_jt","symbol":"P_{jt}","meaning":"Real power exchange of microgrid j at the PCC with the distribution system in time t; positive/negative direction follows the source convention that the exchange cost is negative when the MG extracts power and positive when it exports.","kind":"operational","domain":"real-valued","unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14","v141-b-g01-E18"]},{"variable_id":"x_pcc_reactive_jt","symbol":"Q_{jt}","meaning":"Reactive power exchange of microgrid j at the PCC with the distribution system in time t.","kind":"operational","domain":"real-valued","unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14","v141-b-g01-E18"]},{"variable_id":"x_participant_active_it","symbol":"P_{it}","meaning":"Real power output/exchange variable for participant category i in time t, printed over i in J,L,M,N in the LLPM capacity constraints; for i in J this is the MG PCC exchange term in the source's i-indexed notation.","kind":"operational","domain":"real-valued; i in J,L,M,N","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"]},{"variable_id":"x_participant_reactive_it","symbol":"Q_{it}","meaning":"Reactive power output/exchange variable for participant category i in time t, printed over i in J,L,M,N in the LLPM capacity constraints; for i in J this is the MG PCC reactive exchange term in the source's i-indexed notation.","kind":"operational","domain":"real-valued; i in J,L,M,N","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"]},{"variable_id":"x_gen_active_kt","symbol":"P_{kt}","meaning":"Real power output of MG generation unit k in time t.","kind":"operational","domain":"real-valued; k in K_j","unit":null,"indices":["k","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"]},{"variable_id":"x_gen_reactive_kt","symbol":"Q_{kt}","meaning":"Reactive power output of MG generation unit k in time t.","kind":"operational","domain":"real-valued; k in K_j","unit":null,"indices":["k","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"]},{"variable_id":"x_islanding_rho_jt","symbol":"\\rho_{jt}","meaning":"Binary variable indicating the working-mode/islanding state of MG j in time t; source states it controls the MG working-mode switch in Case2.","kind":"operational","domain":"{0,1}","unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g02-E43","v141-b-g03-e003"]}],"theta":[{"parameter_id":"theta_dp_jt","symbol":"D^{P}_{jt}","meaning":"Real power consumption/load of the j-th MG in time t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"]},{"parameter_id":"theta_dq_jt","symbol":"D^{Q}_{jt}","meaning":"Reactive power consumption/load of the j-th MG in time t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E14"]},{"parameter_id":"theta_pmin_it","symbol":"P^{\\min}_{it}","meaning":"Minimum real power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (54).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"]},{"parameter_id":"theta_pmax_it","symbol":"P^{\\max}_{it}","meaning":"Maximum real power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (54).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"]},{"parameter_id":"theta_qmin_it","symbol":"Q^{\\min}_{it}","meaning":"Minimum reactive power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (55).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"]},{"parameter_id":"theta_qmax_it","symbol":"Q^{\\max}_{it}","meaning":"Maximum reactive power output/exchange bound for participant i in time t; defined over i in J,L,M,N and applied to MG i in J in the islanding-mode bound (55).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E16","v141-b-g02-E43"]}],"phi":[{"constraint_id":"v141-c-R008-C001","kind":"mathematical","role":"core","statement":"The local distribution-system market-clearing model restricts PCC power exchanges to its feasible set, including exchange capacity bounds. Scope: MG–DS real and reactive power exchanges at the PCC under the distribution-system LLPM.","expression":"P_{it}^{\\min}\\le P_{it}\\le P_{it}^{\\max},\\quad Q_{it}^{\\min}\\le Q_{it}\\le Q_{it}^{\\max},\\quad \\forall t,\\ \\forall i\\in J,L,M,N","formalization_origin":"source","template_id":null,"members":["clearing.local","execution.energy_trade"],"variable_refs":["x_participant_active_it","x_participant_reactive_it"],"parameter_refs":["theta_pmin_it","theta_pmax_it","theta_qmin_it","theta_qmax_it"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E12","v141-b-g01-E16"]},{"constraint_id":"v141-c-R008-C002","kind":"mathematical","role":"core","statement":"Real and reactive MG power balances must ensure that DG generation supplies the entire load and the power exchange at the PCC. Scope: MG real and reactive power balances governing exchanges at the PCC.","expression":"\\sum_{k}P_{kt}=D^{P}_{jt}+P_{jt},\\quad \\sum_{k}Q_{kt}=D^{Q}_{jt}+Q_{jt},\\quad \\forall t,\\ \\forall k\\in K_j,\\ \\forall j\\in J","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["x_pcc_active_jt","x_pcc_reactive_jt","x_gen_active_kt","x_gen_reactive_kt"],"parameter_refs":["theta_dp_jt","theta_dq_jt"],"evidence_ids":["v141-b-g01-E18","v141-b-g01-E14"]},{"constraint_id":"v141-c-R008-C003","kind":"mathematical","role":"core","statement":"Both real and reactive MG exchange bounds are scaled by the binary variable controlling the working-mode switch. Scope: MG–DS real and reactive power exchanges in Case2. Condition: Case2 contingency study of switching between grid-connected and islanded operation.","expression":"\\rho_{jt}P_{it}^{\\min}\\le P_{it}\\le \\rho_{jt}P_{it}^{\\max},\\quad \\rho_{jt}Q_{it}^{\\min}\\le Q_{it}\\le \\rho_{jt}Q_{it}^{\\max},\\quad \\forall t,\\forall i\\in J","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["x_islanding_rho_jt","x_participant_active_it","x_participant_reactive_it"],"parameter_refs":["theta_pmin_it","theta_pmax_it","theta_qmin_it","theta_qmax_it"],"evidence_ids":["v141-b-g02-E43","v141-b-g03-e003"]}],"pi":[{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-169a788abb-p04-c2r3__v141-a-M01-pricing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"ket. Vmin ≤Vbt ≤Vmax : πminbt , πmaxbt , ∀b ∈B, ∀t} (16) ad. ow The objective function of the upper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The DLMPs (λPbt) are endogenously generated from the lower-level programming model (8)–(16) (LLPM), and the MG uses DLMPs as the base bidding/offering price λPb′jt. The real power and reactive power exchange at PCC belong to the feasible set defined by the LLPM as in constraint (8)."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-169a788abb-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"p p g g the feasible set deﬁned by the LLPM as in constraint (8). The LLPM presents the distribution","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The LLPM presents the distribution system market clearing problem with the objective to maximize the social welfare (8), which consists of four terms. The first three terms represent the total cost for the DS: operation cost from DS-owned DGs, power exchange with MG, and the cost of extracting power from utility power system. The last item is total benefits obtained by supplying power to customers. Constraint (9) and (10) guarantee that the DGs’ outputs, MGs power exchange, utility extraction, and load requirement are within a capacity range. The constraints (11)–(16) are DistFlow equations that can be used to describe the complex power flows at each node for DS. Constraints (11) and (12) are real power injection and reactive power injection at each node."},{"evidence_id":"v141-b-g01-E18","location":{"location_id":"src-169a788abb-p04-c2r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"ket. Vmin ≤Vbt ≤Vmax : πminbt , πmaxbt , ∀b ∈B, ∀t} (16) ad. ow The objective function of the upper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The objective function of the upper level programming model (ULPM) is to minimize power generation cost of microgrids, power exchange cost at point of common coupling and load shedding cost. The power exchange cost is negative when MGs are extracting power from the distribution system or positive when MGs are exporting power to the DS. Dispatchable generators in MG are subject to real power output capacity constraint (2), reactive power capacity output constraint (3), ramp up rate (4) and ramp down rate (5). Real power balance equations (6) and reactive power balance equations (7) together ensure that the power generated by DGs is used to supply the entire load and the power exchange at PCC."},{"evidence_id":"v141-b-g02-E43","location":{"location_id":"src-169a788abb-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"ads p p p p y p , and especially in the infancy of MG industry deployment. G3 Case2:Thiscasestudiest","equation_id":"Eqs. (54)-(56)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T-\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours. \\rho_{jt}P_{it}^{\\min}\\le P_{it}\\le\\rho_{jt}P_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (54)\\\\ \\rho_{jt}Q_{it}^{\\min}\\le Q_{it}\\le\\rho_{jt}Q_{it}^{\\max}\\ \\ \\forall t,\\forall i\\in J \\quad (55)\\\\ \\sum_t \\rho_{jt}=T-\\tau\\ \\ \\forall i\\in J \\quad (56)"},{"evidence_id":"v141-b-g01-E03","location":{"location_id":"src-169a788abb-p01-c2r4__v141-a-M01-bidding","page":1,"printed_page":null,"section":"NOMENCLATURE","anchor_text":"Pbt Real power ﬂow at node b in time t. th P(.)t/Q(.)t Real/reactive power output of the MG, DG, uti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Pmax(.)t/Pmin(.)t Maximum/minimum real power output in time t. Qmax(.)t/Qmin(.)t Maximum/minimum reactive power outputs in time t. UR(.)/DR(.) Generator ramp up/down rates. δGit Marginal cost of generation unit i in MG in time t. δLlt Marginal profit of consumer l in DS in time t. δOnt Marginal cost of DG n in DS in time t. δUmt Marginal cost of utility m in time t. O(.) Large positive constant. DPjt/DQjt Real/reactive power consumption for j-th MG in time t. K(.) Incidence matrix. Pbt Real power flow at node b in time t. P(.)t/Q(.)t Real/reactive power output of the MG, DG, utility, consumer in time t. Pinjbt/Qinjbt Real/reactive power injection at node b in time t. Qbt Reactive power flow at node b in time t. Vbt Voltage magnitude at node b in time t. αjt Offering/Bidding price MGj submitted to DS in time t. βjt The j-th MG marginal operation cost in time t. λPbt/λQbt Lagrangian multipliers associated with real/reactive power balance constraints."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-169a788abb-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 35, NO. 1, JANUARY 2020 our Pkt = DPjt + Pjt, ∀t, ∀k ∈Kj, ∀","equation_id":"Eqs. (6)-(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"\\sum_k P_{kt} = D^P_{jt} + P_{jt}, \\forall t, \\forall k \\in K_j, \\forall j \\in J (6) \\quad \\sum_k Q_{kt} = D^Q_{jt} + Q_{jt}, \\forall t, k \\in K_j, \\forall j \\in J (7)"},{"evidence_id":"v141-b-g01-E16","location":{"location_id":"src-169a788abb-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"j m l ce. ar- P itmin ≤Pit ≤P itmax : μpitmin , μpitmax , e if ∀t, ∀i ∈J, L, M, N (9) al- Qmin it ≤Q","equation_id":"Eqs. (9)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"P^{min}_{it} \\le P_{it} \\le P^{max}_{it} : \\mu^{p min}_{it}, \\mu^{p max}_{it}, \\forall t, \\forall i \\in J,L,M,N (9) \\quad Q^{min}_{it} \\le Q_{it} \\le Q^{max}_{it} : \\mu^{q min}_{(.)t}, \\mu^{q max}_{(.)t}, \\forall t, \\forall i \\in J,L,M,N (10)"},{"evidence_id":"v141-b-g03-e003","location":{"location_id":"src-169a788abb-p08-c2r3__v141-a-M01-clearing","page":8,"printed_page":"10","section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"ads p p p p y p , and especially in the infancy of MG industry deployment. G3 Case2:Thiscasestudiest","equation_id":"Eqs. (54)-(56)","figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"formula"},"source_text":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies. We use T -\\tau islanding rules [9] to test the system. By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch. Then we add one more constraint (56) to control the total number of MG islanding hours.\n\\rho_{jt}P_{it}^{\\min} \\le P_{it} \\le \\rho_{jt}P_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{54}\n\\rho_{jt}Q_{it}^{\\min} \\le Q_{it} \\le \\rho_{jt}Q_{it}^{\\max} \\quad \\forall t, \\forall i \\in J \\tag{55}\n\\sum_{t}\\rho_{jt}=T-\\tau \\quad \\forall i \\in J \\tag{56}"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E11","quote":"The real power and reactive power exchange at PCC belong to the feasible set defined by the LLPM as in constraint (8)."},{"evidence_id":"v141-b-g01-E12","quote":"The LLPM presents the distribution system market clearing problem with the objective to maximize the social welfare (8), which consists of four terms."},{"evidence_id":"v141-b-g01-E12","quote":"Constraint (9) and (10) guarantee that the DGs’ outputs, MGs power exchange, utility extraction, and load requirement are within a capacity range."}],[{"evidence_id":"v141-b-g01-E18","quote":"Real power balance equations (6) and reactive power balance equations (7) together ensure that the power generated by DGs is used to supply the entire load and the power exchange at PCC."}],[{"evidence_id":"v141-b-g02-E43","quote":"Case2: This case studies the special occasion that MGs switch working mode from grid-connected to islanding in case of contingencies."},{"evidence_id":"v141-b-g02-E43","quote":"By introducing binary variable \\rho_{jt} with constraints (54), (55) in upper level programming model, the \\rho_{jt} can control the MG working modes switch."},{"evidence_id":"v141-b-g02-E43","quote":"\\rho_{jt}P_{it}^{\\min}\\le P_{it}\\le\\rho_{jt}P_{it}^{\\max}"},{"evidence_id":"v141-b-g02-E43","quote":"\\rho_{jt}Q_{it}^{\\min}\\le Q_{it}\\le\\rho_{jt}Q_{it}^{\\max}"}]],"C2_formalization":{"graph_sha256":"61e6cd05d2ac884f478393d39887e144469805a4f4d2619c4ed6935d2c16c400","applicability":"formalized","reason":"The frozen rule supports formalization from the LLPM capacity bounds (9)-(10), the MG real/reactive balance equations (6)-(7), and the Case2 islanding-mode scaled exchange bounds (54)-(55). The source uses both j and i as MG/participant indices, and constraints (54)-(55) print rho_jt with P_it/Q_it; those irregularities are preserved rather than normalized. B evidence remains unreviewed, so this formalization is provisional and does not claim independent source verification.","bindings":[{"object_id":"x_pcc_active_jt","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"This MG PCC active-power exchange variable appears in the MG balance equations (6)-(7); the frozen graph has no dedicated balance edge, so the object is bound to the execution.energy_trade node whose scope covers MG–DS exchanges at the PCC."},{"object_id":"x_pcc_reactive_jt","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"This MG PCC reactive-power exchange variable appears in the MG balance equations (6)-(7); the frozen graph has no dedicated balance edge, so the object is bound to execution.energy_trade."},{"object_id":"x_participant_active_it","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R008-E001"],"rationale":"The i-indexed active-power variable is constrained by LLPM capacity bounds (9)-(10), which define the clearing feasible set and limit the PCC exchange; the frozen limits edge E001 from clearing.local to execution.energy_trade represents this restriction. The same symbol is printed in the Case2 bounds (54)."},{"object_id":"x_participant_reactive_it","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R008-E001"],"rationale":"The i-indexed reactive-power variable is constrained by LLPM capacity bounds (9)-(10) and appears in the Case2 reactive bound (55); the limits edge E001 represents the clearing-to-execution restriction."},{"object_id":"x_gen_active_kt","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"MG generation-unit active output appears on the left side of the MG real-power balance (6), whose scope is the PCC exchange execution."},{"object_id":"x_gen_reactive_kt","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"MG generation-unit reactive output appears on the left side of the MG reactive-power balance (7), whose scope is the PCC exchange execution."},{"object_id":"x_islanding_rho_jt","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The binary rho_jt scales both MG exchange bounds in Case2 constraints (54)-(55); it is bound to the execution.energy_trade node because the frozen graph has no separate islanding-state node or edge."},{"object_id":"theta_dp_jt","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"MG real load D^P_jt appears on the right side of balance (6), which must be met by DG generation plus PCC exchange."},{"object_id":"theta_dq_jt","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"MG reactive load D^Q_jt appears on the right side of balance (7), which must be met by DG generation plus PCC exchange."},{"object_id":"theta_pmin_it","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R008-E001"],"rationale":"Minimum real-power bound appears in LLPM capacity constraint (9) and in the scaled Case2 bound (54); edge E001 represents the clearing-to-execution limiting relation for the PCC exchange."},{"object_id":"theta_pmax_it","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R008-E001"],"rationale":"Maximum real-power bound appears in LLPM capacity constraint (9) and in the scaled Case2 bound (54); edge E001 represents the clearing-to-execution limiting relation for the PCC exchange."},{"object_id":"theta_qmin_it","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R008-E001"],"rationale":"Minimum reactive-power bound appears in LLPM capacity constraint (10) and in the scaled Case2 bound (55); edge E001 represents the clearing-to-execution limiting relation for the PCC exchange."},{"object_id":"theta_qmax_it","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R008-E001"],"rationale":"Maximum reactive-power bound appears in LLPM capacity constraint (10) and in the scaled Case2 bound (55); edge E001 represents the clearing-to-execution limiting relation for the PCC exchange."},{"object_id":"v141-c-R008-C001","node_ids":["clearing.local","execution.energy_trade"],"edge_ids":["v141-c-R008-E001"],"rationale":"C001 formalizes the LLPM capacity bounds (9)-(10) as the restriction of PCC exchange variables to the clearing feasible set; this matches the frozen limits edge from clearing.local to execution.energy_trade."},{"object_id":"v141-c-R008-C002","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"C002 formalizes MG real/reactive balances (6)-(7) ensuring DG generation supplies load plus PCC exchange; the frozen graph provides only the execution.energy_trade member for this balance constraint."},{"object_id":"v141-c-R008-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"C003 formalizes Case2 bounds (54)-(55) with rho_jt scaling the MG exchange limits; the frozen graph provides only the execution.energy_trade member for this conditional islanding-mode constraint."}],"revision_requests":[]}},"quarantined_references":[]}});
